<script>
document.addEventListener('DOMContentLoaded',()=>{const state=document.getElementById('sms-state'),lga=document.getElementById('sms-lga'),ward=document.getElementById('sms-ward'),pu=document.getElementById('sms-polling_unit');if(!state)return;const reset=e=>e.replaceChildren(new Option('All permitted',''));async function load(type,target){reset(target);const query=new URLSearchParams();if(state.value)query.set('state_id',state.value);if(lga.value)query.set('lga_id',lga.value);if(ward.value)query.set('ward_id',ward.value);try{const r=await fetch(@json(route($prefix.'locations',['type'=>'__TYPE__'])).replace('__TYPE__',type)+'?'+query,{headers:{Accept:'application/json'}});if(!r.ok)return;const data=await r.json();for(const row of data.data)target.add(new Option(row.name,row.id));}catch{}}state.addEventListener('change',()=>{reset(lga);reset(ward);reset(pu);if(state.value)load('lgas',lga)});lga.addEventListener('change',()=>{reset(ward);reset(pu);if(lga.value)load('wards',ward)});ward.addEventListener('change',()=>{reset(pu);if(ward.value)load('polling_units',pu)});});
</script>
